import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { changeSetting, listSettings, settingsKey, SETTING_DEFAULTS, SETTING_KEYS } from './api';

/** The sheet's settings: each one's value in force and a form that changes them. A field shows the
 *  value in force until it is edited; saving saves the fields entered (every field when none was). */
export function Settings({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  const current = (key: string) =>
    settings.data?.find((s) => s.key === key)?.value ?? SETTING_DEFAULTS[key] ?? '';
  const [form, setForm] = useState<Record<string, string>>({});

  const save = useMutation({
    mutationFn: async (values: Record<string, string>) => {
      for (const [key, value] of Object.entries(values)) await changeSetting(sheetId, user, key, value);
    },
    onSettled: () => queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) }),
  });

  const submitOnce = useSubmitOnce();

  const enter = (key: string) => setForm((f) => (key in f ? f : { ...f, [key]: current(key) }));

  const change = (key: string, value: string) => {
    setForm((f) => ({ ...f, [key]: value }));
    save.reset();
  };

  return (
    <section>
      <h3>Settings</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          const values = Object.keys(form).length > 0 ? form
            : Object.fromEntries(SETTING_KEYS.map((key) => [key, current(key)]));
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(values).then(() => setForm({}));
          });
        }}
      >
        {SETTING_KEYS.map((key) => (
          <div key={key}>
            <label>
              {key === 'clerk-limit' ? 'Clerk limit' : key === 'floor' ? 'Floor' : key === 'late-pct' ? 'Late percent'
                : key === 'policy-date' ? 'Policy date' : key === 'period-numbering-from' ? 'Period numbering from'
                : key.startsWith('terms-') ? `Terms for grade ${key.slice('terms-'.length)} (days)` : 'Terms (days)'}{' '}
              <input data-testid={`setting-${key}`} value={form[key] ?? current(key)}
                placeholder={key === 'clerk-limit' ? 'No limit' : key === 'policy-date' ? 'Today (yyyy-MM-dd)'
                  : key === 'period-numbering-from' ? 'Off (yyyy-MM-dd)' : key.startsWith('terms-') ? "Sheet's terms" : undefined}
                onFocus={() => enter(key)} onChange={(e) => change(key, e.target.value)} />
            </label>{' '}
            Now: <span data-testid={`setting-${key}-current`}>{current(key)}</span>
          </div>
        ))}
        <button type="submit" data-testid="settings-save" disabled={save.isPending}>
          Save settings
        </button>
        {save.isError && (
          <span data-testid="settings-error">
            The clerk limit must be blank, and the floor given, as 0.00 or more with up to two decimals;
            the terms a whole number of days, and a grade's terms blank or a whole number of days; the late percent 0.00 or more with up to two decimals; the policy date and period numbering date blank or a date.
          </span>
        )}
      </form>
    </section>
  );
}
import { useQuery } from '@tanstack/react-query';
import { getJson, postJson } from '../../api/http';
import { sheetKey } from '../sheet/api';
import type { Late } from '../rates/api';

/** A sheet setting: its value as text ("" when blank). A setting never set is not listed. */
export type Setting = { sheetId: string; key: string; value: string };
/** The role a user name has on the sheet; a name not listed is a clerk. */
export type Role = { sheetId: string; user: string; role: string };

/** The settings the screen offers: the clerk limit (two decimals; blank means no limit), the
 *  floor (two decimals; the least a claim's live due can be) and the terms (whole days after its
 *  date by which a claim is due) and the late percent (two decimals; the share of an overdue claim's
 *  figure it gains for every full 30 days it is overdue) and the policy date (yyyy-MM-dd; blank means
 *  the sheet's today: a claim dated before it rounds half up, on or after it half to even) and the
 *  period numbering date (yyyy-MM-dd; blank means off: once the sheet's today is on or after it, a
 *  claim opened is numbered within its period, <period>-<n>, or X-<n> in no period). A grade's own terms
 *  (terms-<grade>; blank means the sheet's terms) fix the due-by of a claim added for a person of that
 *  grade on its date: its date plus those terms, kept when the terms or its date change later. */
export const SETTING_KEYS = ['clerk-limit', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'late-pct', 'policy-date',
  'period-numbering-from'] as const;

/** A setting's value until it is first set. */
export const SETTING_DEFAULTS: Record<string, string> = { floor: '1.00', terms: '14', 'late-pct': '0.00' };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}`;

export const settingsKey = (sheetId: string) => [...sheetKey(sheetId), 'settings'] as const;
export const rolesKey = (sheetId: string) => [...sheetKey(sheetId), 'roles'] as const;

export function listSettings(sheetId: string): Promise<Setting[]> {
  return getJson<Setting[]>(`${base(sheetId)}/settings`);
}

/** Change a setting; refused (rejects) when the value is not valid for it. */
export function changeSetting(sheetId: string, by: string, key: string, value: string): Promise<Setting> {
  return postJson<Setting>(`${base(sheetId)}/settings?by=${encodeURIComponent(by)}`, { key, value });
}

export function listRoles(sheetId: string): Promise<Role[]> {
  return getJson<Role[]>(`${base(sheetId)}/roles`);
}

/** Assign a user name a role; refused (rejects) when the role is not clerk or steward. */
export function setRole(sheetId: string, by: string, user: string, role: string): Promise<Role> {
  return postJson<Role>(`${base(sheetId)}/roles?by=${encodeURIComponent(by)}`, { user, role });
}

/** The sheet's floor: the least a claim's live due can be. */
export function useFloor(sheetId: string): string {
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  return settings.data?.find((s) => s.key === 'floor')?.value || SETTING_DEFAULTS.floor;
}

/** What a claim's late charge and rounding go by: the sheet's late percent, today and policy
 *  date (its today when blank). */
export function useLate(sheetId: string, today: string): Late {
  const settings = useQuery({ queryKey: settingsKey(sheetId), queryFn: () => listSettings(sheetId) });
  const pct = settings.data?.find((s) => s.key === 'late-pct')?.value || SETTING_DEFAULTS['late-pct'];
  const policy = settings.data?.find((s) => s.key === 'policy-date')?.value || today;
  return { pct, today, policy };
}
import { useQuery } from '@tanstack/react-query';
import { claimsKey, listClaims } from '../claims/api';
import { listPeople, peopleKey } from '../people/api';
import { useDueTotal } from '../rates/DueTotal';
import { useOverdue } from '../rates/Overdue';
import { STATUSES, statusCount } from './Summary';

/** The sheet's header counters, shown at all times: everyone on the sheet (retired included), the
 *  claims per status (as the summary counts them), and the sheet's due- and overdue-totals. */
export function Header({ sheetId, user }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const dueTotal = useDueTotal(sheetId, user);
  const late = useOverdue(sheetId, user);
  return (
    <header>
      People <span data-testid="header-people-count">{(people.data ?? []).length}</span>
      {STATUSES.map((s) => (
        <span key={s}>
          {' · '}{s} <span data-testid={`header-claims-${s}-count`}>{statusCount(claims.data, s)}</span>
        </span>
      ))}
      {' · '}Due <span data-testid="header-due-total">{dueTotal}</span>
      {' · '}Overdue <span data-testid="header-overdue-total">{late.total}</span>
    </header>
  );
}
import { SheetBody } from '../../slots/defs/sheetBody';
import { Header } from './Header';
import { Summary } from './Summary';

export const contributions = [
  SheetBody.fill({ order: -100, Component: Header }),
  SheetBody.fill({ order: 27, Component: Summary }),
];
import { useQuery } from '@tanstack/react-query';
import { claimsKey, listClaims, liveClaims, type Claim } from '../claims/api';
import { GRADES, gradeOn, listPeople, peopleKey } from '../people/api';
import { listPeriods, periodDueTotal, periodsKey } from '../periods/api';
import { listRates, personDue, rateByGrade, ratesKey, sumDues } from '../rates/api';
import { useFloor, useLate } from '../settings/api';
import { useSheetToday } from '../sheet/api';

/** Every status a claim's count is shown for. */
export const STATUSES = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'] as const;

/** How many of the sheet's claims have the status. */
export function statusCount(claims: Claim[] | undefined, status: (typeof STATUSES)[number]): number {
  return (claims ?? []).filter((c) => c.status === status).length;
}

/** The sheet's summary, agreeing with the lists: per grade, how many people not retired are on it
 *  today and their due-totals added up (n/a ones skipped); per period, its due-total; per status,
 *  how many claims have it. */
export function Summary({ sheetId, user }: { sheetId: string; user: string }) {
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const periods = useQuery({ queryKey: periodsKey(sheetId), queryFn: () => listPeriods(sheetId) });
  const floor = useFloor(sheetId);
  const today = useSheetToday(sheetId, user);
  const charges = useLate(sheetId, today);
  const byGrade = rateByGrade(rates.data, today);
  const all = claims.data ?? [];
  const active = (people.data ?? []).filter((p) => !p.retired);
  const dueOf = (p: (typeof active)[number]) => personDue(liveClaims(all.filter((c) => c.personId === p.id), [p]),
    rates.data, (d) => gradeOn(p, d), byGrade.get(p.grade), floor, charges);

  return (
    <section>
      <h3>Summary</h3>
      <table>
        <tbody>
          {GRADES.map((g) => {
            const on = active.filter((p) => p.grade === g);
            return (
              <tr key={g}>
                <td>Grade {g}</td>
                <td>People <span data-testid={`summary-grade-${g}-count`}>{on.length}</span></td>
                <td>Due <span data-testid={`summary-grade-${g}-due-total`}>{sumDues(on.map(dueOf))}</span></td>
              </tr>
            );
          })}
          {(periods.data ?? []).map((p) => (
            <tr key={p.name}>
              <td>Period {p.name}</td>
              <td />
              <td>Due <span data-testid={`summary-period-${p.name}-due-total`}>
                {periodDueTotal(p, all, people.data, rates.data, floor, charges)}</span></td>
            </tr>
          ))}
          {STATUSES.map((s) => (
            <tr key={s}>
              <td>{s}</td>
              <td>Claims <span data-testid={`summary-status-${s}-count`}>{statusCount(all, s)}</span></td>
              <td />
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
